const scenarios={shopping:{title:'Two concurrent product searches',text:'Find headphones at most 150 USD and keyboards at most 100 USD. Show the cheapest matching product in each category, with its price and source.',note:'Two independent subagents run concurrently.',steps:['Interpret two product intents','Search both categories concurrently','Validate prices and sources','Moderator selects the cheapest in each category']},travel:{title:'Research, then assemble an itinerary',text:'Plan a three-day Toronto trip with architecture, food, and waterfront stops. Keep the plan practical and show the source for every stop.',note:'The detail subagent waits for destination research.',steps:['Interpret destination and interests','Research relevant Toronto places','Pass source URLs to the dependent worker','Moderator assembles evidence-backed stops']},jobs:{title:'Search, inspect, then rank jobs',text:'Find remote software engineering jobs and show the three highest salaries with company and source.',note:'Ranking happens only after validation.',steps:['Interpret role, remote, salary, and limit criteria','Search matching jobs','Open details in a dependent worker','Validate, filter, and rank salaries']}};
const stages=['interpreting','gating','planning','matching','dispatching','reconciling','validating','synthesizing','publishing','completed'];let scenario='shopping',activeRun=null,source=null,events=[],snapshot=null,selected=null;const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>{const n=document.createElement('span');n.textContent=v;return n.innerHTML};
function setScenario(name){scenario=name;$$('[data-scenario]').forEach(b=>b.setAttribute('aria-selected',b.dataset.scenario===name));$('#missionText').value=scenarios[name].text;$('#scenarioNote').textContent='Example loaded. Edit it freely; ARGUS classifies the request from the text.';$('#previewTitle').textContent=scenarios[name].title;$('#previewSteps').innerHTML=scenarios[name].steps.map((s,i)=>`<li><b>${i+1}</b>${s}</li>`).join('')}
function view(name){$$('.view').forEach(v=>v.hidden=v.id!==`${name}View`);$$('[data-view]').forEach(a=>a.toggleAttribute('aria-current',a.dataset.view===name));$('#viewLabel').textContent=name==='workflow'?'Live workflow':name[0].toUpperCase()+name.slice(1);if(name==='runs')loadRuns('#allRuns')}
const runtimeCopy={live:['Live Steel runtime','Real ARGUS orchestration<br>Current public websites'],controlled:['Controlled fixture runtime','Real ARGUS orchestration<br>Fixture records, no websites visited']};
async function loadRuntime(){try{const h=await api('/api/health'),copy=runtimeCopy[h.runtime]||[`Runtime: ${h.runtime}`,'Unrecognized mode'];$('#runtimeBox').dataset.runtime=h.runtime;$('#runtimeTitle').textContent=copy[0];$('#runtimeDetail').innerHTML=copy[1]}catch(_){$('#runtimeBox').dataset.runtime='unknown';$('#runtimeTitle').textContent='Runtime unknown';$('#runtimeDetail').textContent='API unavailable'}}
function showFormError(message){const el=$('#formError');el.hidden=!message;el.textContent=message||''}
const fixtureBadge=runtime=>runtime==='controlled'?'<em class="badge fixture">Fixture data</em>':'';
async function api(path,options){const r=await fetch(path,options),d=await r.json();if(!r.ok)throw Error(d.detail||'Request failed');return d}
async function launch(e){e.preventDefault();$('#runButton').disabled=true;showFormError('');try{const created=await api('/api/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:$('#missionText').value})});scenario=created.scenario;activeRun=created.run_id;events=[];selected=null;location.hash='workflow';connect(activeRun)}catch(err){showFormError(err.message)}finally{$('#runButton').disabled=false}}
function connect(id){source?.close();$('#activeRunLabel').textContent=id;$('#workflowTitle').textContent=scenarios[scenario].title;$('#workflowSubtitle').textContent=$('#missionText').value;$('#workflowStatus').textContent='Running';$('#workflowStatus').className='badge running';$('#cancelButton').disabled=false;renderStages('created');renderTimeline();source=new EventSource(`/api/runs/${id}/events`);source.addEventListener('argus',m=>{const e=JSON.parse(m.data);if(!events.some(x=>x.sequence===e.sequence))events.push(e);selected=e;renderTimeline();renderEvent(e);renderStages(e.stage);if(e.type.startsWith('run_')&&/(completed|failed|cancelled|needs_input)/.test(e.type))finish()});source.onerror=()=>finish()}
async function finish(){source?.close();source=null;if(!activeRun)return;try{snapshot=await api(`/api/runs/${activeRun}`);const status=snapshot.status;$('#workflowStatus').textContent=status;$('#workflowStatus').className=`badge ${status}`;$('#cancelButton').disabled=true;renderStages(status==='succeeded'?'completed':status);renderResult(snapshot);loadRuns('#recentRuns')}catch(_){$('#workflowStatus').textContent='Disconnected'}}
function renderStages(stage){const current=stages.indexOf(stage==='succeeded'?'completed':stage);$('#stageRail').innerHTML=stages.map((s,i)=>`<div class="stage ${i<current?'done':i===current?'active':''}"><b>${i+1}</b><small>${s}</small></div>`).join('')}
function actor(e){if(e.type==='match_decided'||e.type.includes('skill'))return'Ghost';if(/assessed|reconcil|synth/.test(e.type))return'Moderator';if(/subtask|worker_action/.test(e.type))return e.data?.subtask_id||'Subagent';return'ARGUS'}
function renderTimeline(){$('#eventCount').textContent=`${events.length} event${events.length===1?'':'s'}`;if(!events.length)return;$('#timeline').innerHTML=events.map(e=>`<button class="event ${selected?.sequence===e.sequence?'selected':''}" data-id="${e.sequence}"><b>${String(e.sequence).padStart(2,'0')}</b><i></i><span><small>${actor(e)} · ${e.stage}</small><strong>${esc(e.message)}</strong><em>${e.type.replaceAll('_',' ')}</em></span></button>`).join('');$$('.event').forEach(b=>b.onclick=()=>{selected=events.find(e=>e.sequence===+b.dataset.id);renderTimeline();renderEvent(selected)});$('#timeline').scrollTop=$('#timeline').scrollHeight}
function renderEvent(e){$('#detailTitle').textContent=e.message;const d=e.data||{},rows=[['Actor',actor(e)],['Stage',e.stage],['Event',e.type.replaceAll('_',' ')],['Subagent',d.subtask_id],['Decision',d.decision||d.mode],['Action',d.action],['Target',d.semantic_target],['Outcome',d.outcome],['Evidence',d.observation_after||d.observation_id]].filter(r=>r[1]!=null);$('#detailBody').innerHTML=`<dl>${rows.map(r=>`<div><dt>${r[0]}</dt><dd>${esc(String(r[1]))}</dd></div>`).join('')}</dl><details><summary>Raw event</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>`}
function renderResult(run){const p=$('#resultPanel'),a=run.answer||{},records=a.records||[];p.hidden=false;p.innerHTML=`<header><span><small>Controller-published conclusion</small><h2>${run.status==='succeeded'?'Validated result':'No validated result'}</h2></span><span class="workflow-actions">${fixtureBadge(run.runtime)}<em class="badge ${run.validation?.status||run.status}">${run.validation?.status||run.status}</em></span></header><div class="answers">${(a.lines||[]).map(l=>`<p>${esc(l)}</p>`).join('')}</div>${records.length?`<div class="records">${records.map(r=>`<article><strong>${esc(r.title||'Result')}</strong>${Object.entries(r).filter(x=>!['title','source_observation_id','retrieved_at'].includes(x[0])).map(([k,v])=>k==='url'?`<a href="${esc(v)}" target="_blank" rel="noreferrer">Open source ↗</a>`:`<span><small>${k.replaceAll('_',' ')}</small>${esc(String(v))}</span>`).join('')}<footer>Evidence: ${esc(r.source_observation_id||'none')}</footer></article>`).join('')}</div>`:''}`}
async function loadRuns(target){try{const runs=await api('/api/runs');$(target).innerHTML=runs.length?runs.map(r=>`<button class="run" data-run="${r.run_id}" data-scenario="${r.scenario||'shopping'}"><span><small>${r.scenario||'mission'}</small><strong>${r.run_id}</strong></span><span class="workflow-actions">${fixtureBadge(r.runtime)}<em class="badge ${r.status}">${r.status}</em></span><b>→</b></button>`).join(''):'<p class="empty">No runs yet.</p>';$$(`${target} .run`).forEach(b=>b.onclick=async()=>{activeRun=b.dataset.run;scenario=b.dataset.scenario;snapshot=await api(`/api/runs/${activeRun}`);events=await api(`/api/runs/${activeRun}/event-log`);selected=events.at(-1);location.hash='workflow';$('#workflowTitle').textContent=scenarios[scenario]?.title||'ARGUS run';$('#workflowSubtitle').textContent=snapshot.interpreted?.raw_text||'';renderTimeline();if(selected)renderEvent(selected);renderResult(snapshot);renderStages(snapshot.status==='succeeded'?'completed':snapshot.status);$('#activeRunLabel').textContent=activeRun;$('#workflowStatus').textContent=snapshot.status;$('#workflowStatus').className=`badge ${snapshot.status}`})}catch(e){$(target).innerHTML=`<p class="empty">API unavailable: ${esc(e.message)}</p>`}}
$$('[data-scenario]').forEach(b=>b.onclick=()=>setScenario(b.dataset.scenario));$('#missionForm').onsubmit=launch;$('#cancelButton').onclick=()=>activeRun&&api(`/api/runs/${activeRun}/cancel`,{method:'POST'});$('#refreshRuns').onclick=()=>loadRuns('#recentRuns');$('#refreshAllRuns').onclick=()=>loadRuns('#allRuns');$('#themeToggle').onclick=()=>document.documentElement.dataset.theme=document.documentElement.dataset.theme==='midnight'?'paper':'midnight';addEventListener('hashchange',()=>view((location.hash||'#mission').slice(1)));setScenario('shopping');view((location.hash||'#mission').slice(1));loadRuntime();loadRuns('#recentRuns');
